<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="form-card"><p class="eyebrow">Staff account</p><h1><?= esc($title) ?></h1><?php $errors=session()->getFlashdata('errors')??[]; if($errors): ?><div class="alert error"><ul><?php foreach($errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form action="<?= esc($action) ?>" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label>Username *</label><input name="username" value="<?= esc(old('username',$user['username']??'')) ?>" required><label>Full name *</label><input name="full_name" value="<?= esc(old('full_name',$user['full_name']??'')) ?>" required><label>Password <?= $user?'(leave blank to keep current password)':'*' ?></label><input type="password" name="password" <?= $user?'':'required' ?> minlength="8"><label>Avatar</label><input type="file" name="avatar" accept=".jpg,.jpeg,.png"><p class="help">JPG or PNG, maximum 2 MB.</p><div class="form-actions"><button class="button">Save Staff</button><a class="button secondary" href="<?= site_url('users') ?>">Cancel</a></div></form></div><?= $this->endSection() ?>
